// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 time) public {
        vm.assume(value == 10 ether);
        vm.assume(time > c.pastBlockTime());
        vm.warp(time);

        (bool ok, ) = address(c).call{value: value}("");

        if (!ok) {
            // If revert, pastBlockTime unchanged
            assertTrue(c.pastBlockTime() == 0);
        } else {
            // If success
            if (block.number % 15 == 0) {
                // pastBlockTime could be anything; just check it's a valid timestamp
                assertTrue(c.pastBlockTime() >= 0);
            } else {
                // pastBlockTime must be > 0 (since it was set to block.timestamp which is > 0)
                assertTrue(c.pastBlockTime() > 0);
            }
        }
    }
}

